import json
R='/project1/glsl_test_6'
results={}
for c in op(R).children:
    if c.type==td.glslPOP:
        results['glsl_name']=c.name
        results['glsl_errors']=str(c.errors())
        results['outputattrs']=c.par.outputattrs.eval()
        results['numelems']=c.par.numelems.eval()
        results['computedat']=c.par.computedat.eval()
    if c.type==td.textDAT and 'info' in c.name.lower():
        try:
            info_text=c.text
            results['info_text']=info_text[:1000] if info_text else '(empty)'
        except:
            results['info_text']='(error reading)'
    if c.type==td.gridPOP:
        results['source_type']='gridPOP'
        results['rows']=c.par.rows.eval()
        results['cols']=c.par.cols.eval()
results['children_count']=len(op(R).children)
results['children_names']=[str(c.name) for c in op(R).children]
print(json.dumps(results))
